template<size_t N>bool reference_parse(S row,std::array<S,N>&out,Q* layout=nullptr){if(layout)*layout=row.size()>255?(Q(1)<<63)|row.size():0;size_t begin=0;for(size_t i=0;i<N;i++){auto comma=row.find(',',begin);if(i+1<N){if(comma==S::npos)return false;}else if(comma!=S::npos)return false;size_t end=comma==S::npos?row.size():comma;if(layout&&row.size()<=255)*layout|=Q(end)<<(i*8);S s=row.substr(begin,end-begin);if(!s.empty()&&s.front()=='"'){if(s.size()<2||s.back()!='"')return false;s.remove_prefix(1);s.remove_suffix(1);if(s.find('"')!=S::npos)return false;}else if(s.find('"')!=S::npos)return false;out[i]=s;begin=end+1;}return true;}